import Foundation

// MARK: - Words into cues

/// The five cue rules, and the ONLY place they live: at most two lines, at
/// most 42 characters a line, at most six seconds a cue, at least a frame
/// between cues, and never two speakers in one cue. Recognised words in,
/// `CaptionLayout.Cue`s out.
///
/// **It is beside `CaptionLayout` and it is not part of it.** `CaptionImporter`
/// must never reach this: a SubRip file supplies its own line breaks and its
/// own cue lengths, and re-wrapping what somebody already wrote would change
/// every caption file that imports correctly today and break the export's
/// round trip. Only a producer that has to INVENT line breaks — the
/// transcriber — calls it. It sits in this file rather than in
/// `Transcriber.swift` because that file is already at the size where the
/// engine is all it should hold, and because everything here is arithmetic
/// over values with no `Speech` in it at all: hand it a word list with times
/// and it is testable with no recogniser, no grant and no machine.
///
/// **The rules are the producer's, so the layout's trim pass never fires on a
/// transcript.** The frame of gap is the point: `CaptionLayout.place` cuts an
/// overlapping cue back to abut its successor, and a transcript that arrived
/// needing that would be a transcript whose captions had been silently
/// retimed. Snapping cannot undo it either — a whole frame subtracted from a
/// time survives being rounded to the frame grid — so a cue built here is a
/// cue that lands.
enum CaptionCues {

    /// One recognised word, already mapped to PROJECT time by whoever
    /// recognised it. `end` is one tick past its last, like every other span
    /// in this app.
    struct Word: Equatable {
        let text: String
        let start: Ticks
        let end: Ticks
        /// Who said it, when the producer knows — AssemblyAI's `speaker`
        /// with `speaker_labels` on (road map 6 §5f). Nil everywhere else,
        /// which is what keeps every existing caller and the harness's
        /// `cues` mode byte-identical to what they were: the fifth rule
        /// compares nil to nil and never fires.
        let speaker: String?

        init(text: String, start: Ticks, end: Ticks, speaker: String? = nil) {
            self.text = text
            self.start = start
            self.end = max(start, end)
            self.speaker = speaker
        }
    }

    /// Two lines is what a viewer reads without looking away from the
    /// picture, and 42 characters is the line length every broadcast caption
    /// guideline lands on; six seconds is about as long as one screenful of
    /// words stays useful. The fifth rule has no constant: a speaker change
    /// is a change, and there is no threshold to tune.
    static let maxLines = 2
    static let maxCharacters = 42
    static let maxLength: Ticks = ReelTime.ticks(seconds: 6)

    /// Words into cues. `frame` is the canvas frame duration — the gap.
    ///
    /// A word too long for a line of its own is left over-long rather than
    /// broken: a hyphen inserted in the middle of a word is a worse caption
    /// than a wide one, and the clip carries `text.width` anyway, so CoreText
    /// soft-wraps it on the canvas. For the same reason the hard `"\n"` this
    /// puts between the two lines is advisory: it is a break CoreText will
    /// honour, inside a box that may add more.
    ///
    /// Each cue carries its words' speaker with `media`, the transcript's
    /// own, so `place` can colour it (spec §11 R6-22).
    static func build(
        from words: [Word], frame: Ticks, clip: UInt32? = nil, media: UInt32? = nil
    ) -> [CaptionLayout.Cue] {
        var raw: [(start: Ticks, end: Ticks, lines: [String], speaker: String?)] = []
        var lines: [String] = []
        var start: Ticks = 0
        var end: Ticks = 0
        var speaker: String?

        func flush() {
            guard !lines.isEmpty else { return }
            raw.append((start, end, lines, speaker))
            lines = []
        }

        for word in words.sorted(by: { $0.start < $1.start }) {
            let text = word.text.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !text.isEmpty else { continue }
            guard !lines.isEmpty else {
                lines = [text]
                start = word.start
                end = word.end
                speaker = word.speaker
                continue
            }
            // The fifth rule (road map 6 §5f): a word whose speaker differs
            // from the open cue's flushes it, so no cue ever carries two
            // voices. It is tested BEFORE placement rather than inside the
            // placement test, because a speaker change that happened to fit
            // the line and the six seconds would otherwise be placed and the
            // rule would never fire. One break, never an empty cue: the flush
            // is followed by opening a new cue on this word, exactly as the
            // length and the line rules do.
            if word.speaker != speaker {
                flush()
                lines = [text]
                start = word.start
                end = word.end
                speaker = word.speaker
                continue
            }
            var placed = false
            // The six-second rule is tested against the word's END, because a
            // cue is on screen until its last word has been said.
            if word.end - start <= maxLength {
                let last = lines[lines.count - 1]
                if last.count + 1 + text.count <= maxCharacters {
                    lines[lines.count - 1] = last + " " + text
                    placed = true
                } else if lines.count < maxLines {
                    lines.append(text)
                    placed = true
                }
            }
            if placed {
                end = max(end, word.end)
            } else {
                flush()
                lines = [text]
                start = word.start
                end = word.end
                speaker = word.speaker
            }
        }
        flush()

        // The gap. A cue ends a frame before the next one starts, or where its
        // last word ended, whichever is earlier. A pair of cues that starts
        // less than two frames apart cannot have both — recognised words do

import Foundation

/// `get_transcript`'s reader (road map "cut-by-transcript" CT-4, spec §11
/// TR-11): one clip's words in TIMELINE ticks, each flagged by TR-8's filler
/// rule, from the media's cached transcript or else from this Mac's
/// recogniser over the clip's own window. Never the network (TR-5). What the
/// recogniser heard is cached per media and language by
/// `DeviceTranscriptCache` (TR-14), which `get_transcript` and the timeline
/// transcript's fill (`TranscriptFill`, TX-12) read.
///
/// Three pieces, kept apart so a probe can reach each one:
/// - `cached(for:url:in:)` is the cache DOOR, and it is `FillerDetector`'s
///   (TR-2's one marker rule, R6-15), not a new one: a transcript is read
///   only when its marker serves `.captions` for the file as it is now.
/// - `cloudWords` and `deviceWords` are the pure MAPPING, R6-10's two
///   conversions (`MediaTranscript.words(for:in:)` for a cached media
///   transcript, `MediaTranscript.project` for an on-device run's stored
///   source ticks), sorted the same way and flagged the same way.
/// - `recognize` is the on-device RUN, `Transcriber.transcribe`'s model
///   questions and its one-job body without the caption paging: blocking,
///   off main, its temporary WAV removed on every exit.
enum TranscriptReader {

    /// One word of the clip, in project (timeline) ticks.
    struct Word: Equatable {
        let text: String
        let start: Ticks
        let end: Ticks
        /// The cached word's speaker label; nil for the on-device engine.
        let speaker: String?
        /// TR-8's spelling (`FillerWords.isFiller`), for either engine.
        let filler: Bool
    }

    /// A media's current cached transcript, and whether it was asked for
    /// filler words.
    struct Cached {
        let file: MediaTranscript.File
        let fillersReported: Bool
    }

    // MARK: - The cache door

    /// The media's cached transcript when its marker serves captions for the
    /// file as it is now; nil when there is none, it does not read, or the
    /// source has changed under it. `fillersReported` is whether the same
    /// cache also serves filler removal (TR-7's door).
    static func cached(for media: MediaSnapshot, url: URL, in cacheDir: URL) -> Cached? {
        guard
            let file = FillerDetector.transcriptFile(
                for: media, url: url, in: cacheDir, use: .captions)
        else { return nil }
        let fillers = FillerDetector.fillersFile(for: media, url: url, in: cacheDir) != nil
        return Cached(file: file, fillersReported: fillers)
    }

    // MARK: - The mapping

    /// A cached media transcript's words for one clip: R6-10's mapping
    /// (`MediaTranscript.words(for:in:)` — a word is the clip's when its
    /// start is in the clip's source window), sorted by start, then end,
    /// then the file's own order.
    static func cloudWords(for job: Transcriber.Job, in file: MediaTranscript.File) -> [Word] {
        let mapped = MediaTranscript.words(for: job, in: file).enumerated().map {
            (index: $0.offset,
             word: Word(
                text: $0.element.text, start: $0.element.start, end: $0.element.end,
                speaker: $0.element.speaker, filler: FillerWords.isFiller($0.element.text)))
        }
        return sortedWords(mapped)
    }

    /// A stored on-device run's words for one clip (TR-14): a word is the
    /// clip's when its source start is in the clip's [sourceIn, sourceIn +
    /// sourceLength) (R6-10's half-open test); its start and `max(start,
    /// end)` map through `MediaTranscript.project`. Sorted as `cloudWords`
    /// sorts. With `moved` (`WordOnsets.moved` over `heard`, one per word),
    /// each start is its moved one, and the window test reads it (TX-16).
    static func deviceWords(
        _ heard: DeviceTranscriptCache.Heard, for job: Transcriber.Job, moved: [Ticks]? = nil
    ) -> [Word] {
        let end = job.sourceIn + job.sourceLength
        var mapped: [(index: Int, word: Word)] = []
        for (index, run) in heard.words.enumerated() {
            let start = moved.flatMap { index < $0.count ? $0[index] : nil } ?? run.start
            guard start >= job.sourceIn else { continue }
            guard start < end else { continue }
            mapped.append(
                (index,
                 Word(
                    text: run.text, start: MediaTranscript.project(start, in: job),
                    end: MediaTranscript.project(max(run.start, run.end), in: job),
                    speaker: nil, filler: FillerWords.isFiller(run.text))))
        }
        return sortedWords(mapped)
    }

    /// By (start, end, source order).
    private static func sortedWords(_ words: [(index: Int, word: Word)]) -> [Word] {
        words.sorted {
            ($0.word.start, $0.word.end, $0.index) < ($1.word.start, $1.word.end, $1.index)
        }.map(\.word)
    }

    // MARK: - The window

    /// A part of the timeline, [from, to) in project ticks, already clamped
    /// to the clip (spec §11 TR-13).
    struct Window: Equatable {
        let from: Ticks
        let to: Ticks
    }

    /// Why a `from`/`to` pair names no part of the clip, in TR-13's
    /// sentences (the dispatcher puts the tool's name in front).
    enum WindowError: LocalizedError, Equatable {
        case empty(from: Ticks, to: Ticks)
        case outside(from: Ticks?, to: Ticks?, clip: UInt32, start: Ticks, end: Ticks)

        var errorDescription: String? {
            switch self {
            case .empty(let from, let to):
                return "to must be after from: the window from \(from) to \(to) ticks "
                    + "(both snapped to frames) is empty."
            case .outside(let from, let to, let clip, let start, let end):
                let bounds = [from.map { "from \($0)" }, to.map { "to \($0)" }]
                    .compactMap { $0 }.joined(separator: " ")
                return "The window \(bounds) is outside clip \(clip), which plays from \(start) "
                    + "to \(end) ticks."
            }
        }
    }

    /// The window a call's (already snapped) bounds name on this clip; nil
    /// when it gave neither. A missing `from` is the clip's start, a missing
    /// `to` its end, and the window is clamped into the clip. Refused as
    /// `.empty` when both were given and `to` is not after `from` (checked
    /// first), and as `.outside` when nothing is left once clamped.
    static func window(from: Ticks?, to: Ticks?, clip job: Transcriber.Job) throws -> Window? {
        guard from != nil || to != nil else { return nil }
        if let from, let to, to <= from { throw WindowError.empty(from: from, to: to) }
        let clipEnd = job.start + job.duration
        let lower = max(from ?? job.start, job.start)
        let upper = min(to ?? clipEnd, clipEnd)
        guard lower < upper else {
            throw WindowError.outside(
                from: from, to: to, clip: job.clip, start: job.start, end: clipEnd)
        }
        return Window(from: lower, to: upper)
    }

    /// The words that overlap the window, in their input order and
    /// unchanged: a word across an edge is kept whole, with its own times. A
    /// word with no length belongs when from <= its start < to.
    static func overlapping(_ words: [Word], in window: Window) -> [Word] {
        words.filter { word in
            word.start < window.to && max(word.end, word.start + 1) > window.from
        }
    }

    /// The SOURCE seconds an on-device run hears either side of a window.
    static let recognitionPadSeconds: Double = 2

    /// The sub-job a windowed on-device run hears: the window widened by
    /// `recognitionPadSeconds` of source on each side, clamped to the clip.
    /// Its `sourceIn` is the padded start's own source time, so the extract
    /// still begins at the job's `in` point — `Transcriber.project`'s premise.
    /// The whole clip answers `job` itself.
    ///
    /// A RAMPED job (spec §11 SR-20 (d)) pads in SOURCE through its map: the
    /// window's ends read as source ticks, widened by the pad, mapped back
    /// (the start floored, the end ceiled, both clamped to the clip); the
    /// sub-job's `sourceIn` and `sourceLength` are read off the map, its tail
    /// as the constant arm's, and it carries the map unchanged.
    static func recognitionJob(_ job: Transcriber.Job, for window: Window) -> Transcriber.Job {
        if let ramp = job.ramp { return recognitionJob(job, for: window, ramp: ramp) }
        let speed = job.speed.isFinite && job.speed > 0 ? job.speed : 1
        let pad = Ticks((recognitionPadSeconds * Double(ReelTime.perSecond) / speed).rounded(.up))
        let clipEnd = job.start + job.duration
        let start = max(job.start, window.from - pad)
        let end = min(clipEnd, window.to + pad)
        if start == job.start && end == clipEnd { return job }
        let sourceIn = job.sourceIn + Ticks((Double(start - job.start) * speed).rounded())
        let sourceLength = end < clipEnd
            ? Ticks((Double(end - start) * speed).rounded())
            : job.sourceIn + job.sourceLength - sourceIn
        return Transcriber.Job(
            clip: job.clip, media: job.media, name: job.name, source: job.source,
            sourceIn: sourceIn, sourceLength: sourceLength, start: start, duration: end - start,
            speed: job.speed)
    }

    /// `recognitionJob`'s ramp arm: the pad is source time, so it is applied
    /// on the map's source column and read back through `clip(atSource:)`.
    private static func recognitionJob(
        _ job: Transcriber.Job, for window: Window, ramp: Transcriber.Job.Ramp
    ) -> Transcriber.Job {
        let map = ramp.map
        let pad = recognitionPadSeconds * Double(ReelTime.perSecond)
        let fromSource = map.source(atClip: Double(window.from - ramp.clipStart))
        let toSource = map.source(atClip: Double(window.to - ramp.clipStart))
        let lowClip = map.clip(atSource: fromSource - pad).rounded(.down)
        let highClip = map.clip(atSource: toSource + pad).rounded(.up)
        let clipEnd = job.start + job.duration
        let start = max(job.start, ramp.clipStart + Ticks(lowClip))
        let end = min(clipEnd, ramp.clipStart + Ticks(highClip))
        if start == job.start && end == clipEnd { return job }
        let sourceIn = Ticks(map.source(atClip: Double(start - ramp.clipStart)).rounded())
        let sourceLength = end < clipEnd
            ? Ticks(map.source(atClip: Double(end - ramp.clipStart)).rounded()) - sourceIn
            : job.sourceIn + job.sourceLength - sourceIn
        return Transcriber.Job(
            clip: job.clip, media: job.media, name: job.name, source: job.source,
            sourceIn: sourceIn, sourceLength: sourceLength, start: start, duration: end - start,
            speed: job.speed, ramp: ramp)
    }

    // MARK: - The on-device run

    /// One clip through this Mac's recogniser, waited for. Off main only:
    /// `SpeechEngine.transcribe` blocks its caller.
    ///
    /// The model questions are `Transcriber.requireModel`, the ones
    /// `Transcriber.transcribe` asks, in its order and with its sentences:
    /// the engine's availability, then whether the ONE chosen locale is
    /// installed (a question that could not be answered is `.unavailable`,
    /// never "not installed"). It never downloads (W-8). The extract is the
    /// clip's own source window, removed on every exit. `progress` gets each
    /// result's end in seconds into the extract (`SpeechEngine.transcribe`'s),
    /// on the analysis task's thread; `get_transcript` passes none.
    static func recognize(
        _ job: Transcriber.Job, language: Transcriber.Language,
        cancel: Transcriber.CancelToken, progress: @escaping (Double) -> Void = { _ in }
    ) throws -> [SpeechEngine.Run] {
        try Transcriber.requireModel(language)
        if cancel.isCancelled { throw Transcriber.TranscribeError.cancelled }
        let extract = try Transcriber().extractAudio(job, cancel: cancel)
        defer { try? FileManager.default.removeItem(at: extract.url) }
        return try SpeechEngine.transcribe(
            file: extract.url, locale: language.locale, seconds: extract.seconds,
            name: job.name, cancel: cancel, progress: progress)
    }
}
import Foundation

/// What this Mac's recogniser heard for `get_transcript` (spec §11 TR-14,
/// #332) and for the timeline transcript's whole-file fill
/// (`TranscriptFill`, TX-12), cached per media and language so a later call
/// inside a stored run answers without recognising again.
///
/// `cache/device-transcripts/<media id>-<language identifier>.json`: one
/// `File` per (media, language), the whole cached state, sorted keys and
/// `.atomic`, written only through `CacheLedger.publish` so it never lands
/// mid-save. It never shares `cache/transcripts/` with AssemblyAI's files,
/// and only `get_transcript` and `get_timeline_transcript` (through
/// `TranscriptFill`, TX-12) read it: captions, Remove Filler Words,
/// `detect_fillers` and `transcribe_for_fillers` never do (TR-7).
///
/// - The KEY is `Stamp`: R6-15's four-field source stamp, the language, the
///   OS version (the recogniser ships with the OS) and `version`. A file of
///   another stamp is a miss, and the next store replaces it whole.
/// - A HIT is the first stored run, in file order, whose source span
///   contains the span the call would hear. A miss runs exactly that span,
///   and the store drops every stored run the new one contains. No gap is
///   filled and no words are merged across runs.
/// - Words are MEDIA source ticks, so another clip, speed or window over the
///   same file reuses them (`TranscriptReader.deviceWords` maps them).
enum DeviceTranscriptCache {

    /// The folder under the document's cache directory.
    static let kind = "device-transcripts"
    /// Bumped when what a stored run means changes; a file of another
    /// version is a miss.
    static let version = 1

    /// One recognised word, in MEDIA source ticks.
    struct Word: Codable, Equatable {
        let text: String
        let start: Ticks
        let end: Ticks
    }

    /// One run of the recogniser: the source span it heard and its words.
    struct Heard: Codable, Equatable {
        let sourceIn: Ticks
        let sourceLength: Ticks
        let words: [Word]

        enum CodingKeys: String, CodingKey {
            case sourceIn = "source_in"
            case sourceLength = "source_length"
            case words
        }

        init(sourceIn: Ticks, sourceLength: Ticks, words: [Word]) {
            self.sourceIn = sourceIn
            self.sourceLength = sourceLength
            self.words = words
        }

        /// A run's seconds into the extract as media source ticks:
        /// `sourceIn + round(clamp(t × 600000, 0, sourceLength))`, the clamp
        /// in `Double` before the conversion. A word with a non-finite time
        /// is dropped.
        init(runs: [SpeechEngine.Run], over job: Transcriber.Job) {
            let length = max(job.sourceLength, 0)
            func source(_ t: Double) -> Ticks {
                let ticks = min(max(t * Double(ReelTime.perSecond), 0), Double(length))
                return job.sourceIn + Ticks(ticks.rounded(.toNearestOrAwayFromZero))
            }
            self.init(
                sourceIn: job.sourceIn, sourceLength: job.sourceLength,
                words: runs.compactMap { run in
                    guard run.start.isFinite, run.end.isFinite else { return nil }
                    return Word(text: run.text, start: source(run.start), end: source(run.end))
                })
        }

        /// Whether this run heard all of [sourceIn, sourceIn + sourceLength).
        /// False for a non-positive length, or an end that overflows.
        func covers(sourceIn: Ticks, sourceLength: Ticks) -> Bool {
            guard sourceLength > 0, self.sourceLength > 0 else { return false }
            let (end, over) = sourceIn.addingReportingOverflow(sourceLength)
            let (ownEnd, ownOver) = self.sourceIn.addingReportingOverflow(self.sourceLength)
            guard !over, !ownOver else { return false }
            return self.sourceIn <= sourceIn && end <= ownEnd
        }
    }

    /// The key a file is current for.
    struct Stamp: Codable, Equatable {
        let source: TranscriptSourceStamp
        let language: String
        let system: String
        let version: Int
    }

    /// What one file holds: its key and the runs stored under it.
    struct File: Codable, Equatable {
        let stamp: Stamp
        let runs: [Heard]
    }

    // MARK: - Where it lives

    /// `cache/device-transcripts/<media id>-<language>.json`.
    static func fileURL(for media: UInt32, language: String, in cacheDir: URL) -> URL {
        directory(in: cacheDir).appendingPathComponent("\(media)-\(language).json")
    }

    private static func directory(in cacheDir: URL) -> URL {
        cacheDir.appendingPathComponent(kind, isDirectory: true)
    }

    // MARK: - Reading

    /// The file, or nil when it is missing, unreadable or of another shape.
    static func read(for media: UInt32, language: String, in cacheDir: URL) -> File? {
        let url = fileURL(for: media, language: language, in: cacheDir)
        guard let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(File.self, from: data)
    }

    /// The first stored run, in file order, that heard all of `job`'s source
    /// span, when the file's stamp is `stamp`; nil otherwise.
    static func lookup(
        _ job: Transcriber.Job, media: UInt32, stamp: Stamp, in cacheDir: URL
    ) -> Heard? {
        guard let file = read(for: media, language: stamp.language, in: cacheDir) else {
            return nil
        }
        guard file.stamp == stamp else { return nil }
        return file.runs.first { $0.covers(sourceIn: job.sourceIn, sourceLength: job.sourceLength) }
    }

    // MARK: - Writing

    /// `file` with `heard` added: under the same stamp, the stored runs
    /// `heard` contains are dropped and `heard` is appended; under another
    /// stamp (or none), `heard` alone.
    static func merged(_ file: File?, adding heard: Heard, stamp: Stamp) -> File {
        guard let file, file.stamp == stamp else { return File(stamp: stamp, runs: [heard]) }
        let kept = file.runs.filter { !heard.covers(sourceIn: $0.sourceIn, sourceLength: $0.sourceLength) }
        return File(stamp: stamp, runs: kept + [heard])
    }

    /// Reads, merges and writes the file whole and `.atomic`, inside one
    /// `CacheLedger.publish` so no save of the package overlaps it. False
    /// for every way it can fail: a run not kept is a run made again.
    @discardableResult
    static func store(_ heard: Heard, media: UInt32, stamp: Stamp, in cacheDir: URL) -> Bool {
        var written = false
        let published = MediaImporter.CacheLedger.shared.publish(in: cacheDir, for: nil) {
            let file = merged(
                read(for: media, language: stamp.language, in: cacheDir), adding: heard,
                stamp: stamp)
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.sortedKeys]
            guard let data = try? encoder.encode(file),
                (try? FileManager.default.createDirectory(
                    at: directory(in: cacheDir), withIntermediateDirectories: true)) != nil
            else { return }
            let url = fileURL(for: media, language: stamp.language, in: cacheDir)
            written = (try? data.write(to: url, options: .atomic)) != nil
        }
        return published && written
    }

    // MARK: - The door

    /// The stamp of `media`'s file as it is now, or nil when there is no
    /// media or the file cannot be stat'ed. Internal for `TranscriptFill`'s
    /// whole-file items (TX-12).
    static func currentStamp(
        _ media: MediaSnapshot?, url: URL, language: String
    ) -> Stamp? {
        guard let media, let source = MediaImporter.CacheStamp.stamp(for: media, url: url) else {
            return nil
        }
        return Stamp(source: source, language: language)
    }

    /// `run`'s words: a stored run that contains its span (`cached` true),
    /// else `recognize()`'s, stored when there is somewhere to keep them,
    /// the run was not cancelled and the file did not change during it.
    /// With no `cacheDir`, no `media` or a file that cannot be stat'ed it
    /// reads nothing and writes nothing. Rethrows `recognize`'s error.
    static func heard(
        _ run: Transcriber.Job, language: String, media: MediaSnapshot?, in cacheDir: URL?,
        cancelled: () -> Bool, recognize: () throws -> [SpeechEngine.Run]
    ) throws -> (heard: Heard, cached: Bool) {
        let stamp = cacheDir == nil ? nil : currentStamp(media, url: run.source, language: language)
        if let cacheDir, let stamp,
            let hit = lookup(run, media: run.media, stamp: stamp, in: cacheDir)
        {
            return (hit, true)
        }
        let heard = Heard(runs: try recognize(), over: run)
        guard let cacheDir, let stamp else { return (heard, false) }
        guard !cancelled() else { return (heard, false) }
        guard currentStamp(media, url: run.source, language: language) == stamp else { return (heard, false) }
        store(heard, media: run.media, stamp: stamp, in: cacheDir)
        return (heard, false)
    }
}

